select i.*
from second_hand_trading.sh_idle_item i
left join second_hand_trading.sh_user u on i.user_id = u.id

    i.idle_status in (1, 2, 3)

        and i.idle_name LIKE CONCAT('%', #{idleName}, '%')


        and i.idle_price >= #{minPrice}


        and i.idle_price <= #{maxPrice}


        and i.idle_label = #{idleLabel}


        and i.idle_place LIKE CONCAT('%', #{idlePlace}, '%')


        and u.nickname LIKE CONCAT('%', #{userNickname}, '%')


        and DATE(i.release_time) BETWEEN #{startTime} AND #{endTime}


        and DATE(i.release_time) >= #{startTime}


        and DATE(i.release_time) <= #{endTime}


order by i.id desc
limit #{begin}, #{nums}

