update second_hand_trading.sh_idle_item
set idle_stock = idle_stock - #{count},
    idle_status = case when idle_stock - #{count} <= 0 then 4 else idle_status end
where id = #{id}
  and idle_status = 1
  and idle_stock >= #{count}
